"use client";

import { useState } from "react";

/** A minimal streaming chat against /api/chat (text stream). Swap it for `useChat` when you need history and tools. */
export default function ChatPage() {
  const [prompt, setPrompt] = useState("");
  const [answer, setAnswer] = useState("");
  const [pending, setPending] = useState(false);

  async function send(event: React.FormEvent) {
    event.preventDefault();
    if (!prompt.trim()) return;
    setPending(true);
    setAnswer("");
    const res = await fetch("/api/chat", { method: "POST", body: JSON.stringify({ prompt }) });
    const reader = res.body!.getReader();
    const decoder = new TextDecoder();
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      setAnswer((a) => a + decoder.decode(value, { stream: true }));
    }
    setPending(false);
  }

  return (
    <main className="mx-auto flex min-h-dvh max-w-2xl flex-col gap-6 px-6 py-16">
      <h1 className="text-3xl font-semibold tracking-tight">Chat</h1>
      <div aria-live="polite" className="min-h-40 whitespace-pre-wrap rounded-xl border p-4">{answer || "The answer will appear here."}</div>
      <form onSubmit={send} className="flex gap-2">
        <input value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder="Ask something…" aria-label="Message" className="h-11 flex-1 rounded-lg border px-3" />
        <button type="submit" disabled={pending} className="h-11 rounded-lg bg-neutral-950 px-5 text-white disabled:opacity-60">{pending ? "…" : "Send"}</button>
      </form>
    </main>
  );
}
